title: Privileged Role Mismanagement
id: SCWE-017
alias: privileged-role-mismanagement
platform: []
profiles: [L1]
mappings:
  scsvs-cg: [SCSVS-AUTH]
  scsvs-scg: [SCSVS-AUTH-1]
