title: Absence of Time-Locked Functions
id: SCWE-020
alias: absence-time-locked-functions
platform: []
profiles: [L1]
mappings:
  scsvs-cg: [SCSVS-AUTH]
  scsvs-scg: [SCSVS-AUTH-2]
  cwe: [840]
