title: Improper Deletion of Mappings
id: SCWE-053
alias: improper-mapping-deletion
platform: []
profiles: [L1]
mappings:
  scsvs-cg: [SCSVS-CODE]
  scsvs-scg: [SCSVS-CODE-1]
  cwe: [459]
