title: Insecure Event Emission
id: SCWE-063
alias: insecure-event-emission
platform: []
profiles: [L1]
mappings:
  scsvs-cg: [SCSVS-COMM]
  scsvs-scg: [SCSVS-COMM-2]
  cwe: [778]
