    function Example() public {
        value = 10;
    }
}
```

### Fixed Contract Example
```solidity
pragma solidity ^0.8.0;

contract Example {
    uint public value;

    // Correct constructor definition (Solidity >=0.4.22)
    constructor() {  // Use "constructor" instead of the contract name
        value = 10;
    }
}
```

