title: Initialization Front-Running in Upgradeable Contracts
id: SCWE-098
alias: initializer-front-running
platform: []
profiles: [L1]
mappings:
  scsvs-cg: [SCSVS-ARCH]
  scsvs-scg: [SCSVS-ARCH-1]
