title: Improper Use of try/catch Leading to Silent Failures
id: SCWE-146
alias: incorrect-try-catch-error-handling
platform: []
profiles: [L1]
mappings:
  scsvs-cg: [SCSVS-CODE]
  scsvs-scg: [SCSVS-CODE-2]
  cwe: [390]
status: new
