title: Permit or Meta-Transaction Signatures Without Expiration
id: SCWE-147
alias: missing-signature-expiration
platform: []
profiles: [L1]
mappings:
  scsvs-cg: [SCSVS-AUTH]
  scsvs-scg: [SCSVS-AUTH-2]
